CardSets.register({"id":"skyrim","name":"Skyrim","code":"SKYR","description":"400 cards from the province of Skyrim — its heroes, dragons, holds, Daedric artifacts and shouts, from the Last Dragonborn and Alduin to Lydia and the humble sweet roll. Dawnguard, Dragonborn and Hearthfire included.","theme":{"primary":"#8fc1e3","secondary":"#232c38","artBackground":"#10151d","artFit":"cover"},"pack":{"name":"Skyrim Pack","emblem":"🐉","skin":"skyrim"},"cards":[{"name":"The Last Dragonborn","rarity":"chase","id":"the-last-dragonborn","subtitle":"Character","details":"Dragonborn hero of prophecy who absorbs dragon souls, masters the Thu'um, and faces Alduin the World-Eater to stop the end of the world.","image":"https://static.wikia.nocookie.net/elderscrolls/images/4/4f/Dovahkiin_%28dragonborn%29.jpg"},{"name":"Lydia","rarity":"chase","id":"lydia","subtitle":"Character","details":"Housecarl granted by Jarl Balgruuf after the Dragonborn's first dragon kill at the Western Watchtower; sworn to carry your burdens.","image":"https://images.uesp.net/6/68/SR-npc-Lydia.jpg"},{"name":"Serana","rarity":"chase","id":"serana","subtitle":"Character","details":"Ancient Daughter of Coldharbour turned by Molag Bal, who defies her father Lord Harkon's plan to blot out the sun with Auriel's Bow.","image":"https://images.uesp.net/a/a1/SR-npc-Serana.jpg"},{"name":"Miraak","rarity":"legendary","id":"miraak","subtitle":"Character","details":"The first Dragonborn, a dragon priest who betrayed his masters for Hermaeus Mora's secrets and rules from the realm of Apocrypha.","image":"https://images.uesp.net/b/b9/SR-npc-Miraak_02.jpg"},{"name":"Lord Harkon","rarity":"legendary","id":"lord-harkon","subtitle":"Character","details":"Ancient Volkihar vampire lord who seeks the Tyranny of the Sun prophecy, hoping to end the sun's reign over his kind forever.","image":"https://images.uesp.net/f/f4/SR-npc-Lord_Harkon.jpg"},{"name":"Ulfric Stormcloak","rarity":"legendary","id":"ulfric-stormcloak","subtitle":"Character","details":"Jarl of Windhelm and leader of the Stormcloak rebellion, who used the Voice to kill High King Torygg and ignite Skyrim's civil war.","image":"https://images.uesp.net/6/6e/SR-npc-Ulfric_Stormcloak.jpg"},{"name":"General Tullius","rarity":"legendary","id":"general-tullius","subtitle":"Character","details":"Imperial general sent to Skyrim as military governor, tasked with crushing the Stormcloak rebellion and beheading its leader.","image":"https://images.uesp.net/1/13/SR-npc-General_Tullius.jpg"},{"name":"Astrid","rarity":"legendary","id":"astrid","subtitle":"Character","details":"Leader of the Dark Brotherhood's last Sanctuary, whose desperate bargain with the Penitus Oculatus dooms the family she tried to save.","image":"https://images.uesp.net/e/e7/SR-npc-Astrid.jpg"},{"name":"Arngeir","rarity":"legendary","id":"arngeir","subtitle":"Character","details":"Spokesman of the Greybeards of High Hrothgar, the only one who can speak to outsiders without his voice shaking the mountain.","image":"https://images.uesp.net/d/d1/SR-npc-Arngeir.jpg"},{"name":"Balgruuf the Greater","rarity":"legendary","id":"balgruuf-the-greater","subtitle":"Character","details":"Jarl of Whiterun, the first jarl to back the Dragonborn, who must choose a side as the civil war closes in on his hold.","image":"https://images.uesp.net/0/00/SR-npc-Balgruuf_the_Greater.jpg"},{"name":"Delphine","rarity":"legendary","id":"delphine","subtitle":"Character","details":"One of the last Blades, hiding as keeper of Riverwood's Sleeping Giant Inn while she hunts for a way to kill the returning dragons.","image":"https://images.uesp.net/7/73/SR-npc-Delphine_02.jpg"},{"name":"Esbern","rarity":"legendary","id":"esbern","subtitle":"Character","details":"Blades loremaster and scholar of dragon lore, hiding from the Thalmor in Riften's Ratway until the Dragonborn comes calling.","image":"https://images.uesp.net/6/69/SR-npc-Esbern.jpg"},{"name":"Kodlak Harbinger","rarity":"legendary","id":"kodlak-harbinger","subtitle":"Character","details":"Harbinger of the Companions, an old werewolf who dreams of Sovngarde and seeks a cure for the beast blood before he dies.","image":"https://images.uesp.net/9/9c/SR-npc-Kodlak_Whitemane.jpg"},{"name":"Brynjolf","rarity":"legendary","id":"brynjolf","subtitle":"Character","details":"The Thieves Guild's charming second-in-command, who spots the Dragonborn's talent in Riften's market and recruits them with a scheme.","image":"https://images.uesp.net/d/de/SR-npc-Brynjolf.jpg"},{"name":"Mercer Frey","rarity":"legendary","id":"mercer-frey","subtitle":"Character","details":"Guildmaster of the Thieves Guild who murdered his predecessor Gallus, stole the Skeleton Key, and drained the Guild's vault for years.","image":"https://images.uesp.net/9/94/SR-npc-Mercer_Frey.jpg"},{"name":"M'aiq the Liar","rarity":"epic","id":"maiq-the-liar","subtitle":"Character","details":"Enigmatic Khajiit wanderer who dispenses cryptic wisdom across Skyrim; M'aiq knows much, tells some, and has heard it all before.","image":"https://images.uesp.net/6/61/SR-npc-M%27aiq_the_Liar.jpg"},{"name":"Cicero","rarity":"epic","id":"cicero","subtitle":"Character","details":"The Night Mother's deranged jester Keeper, who preserves her corpse and the old ways while the rest of the Brotherhood forgets them.","image":"https://images.uesp.net/9/98/SR-npc-Cicero.jpg"},{"name":"Karliah","rarity":"epic","id":"karliah","subtitle":"Character","details":"Nightingale and master thief framed by Mercer Frey for Gallus's murder, who spent 25 years preparing to clear her name.","image":"https://images.uesp.net/a/a6/SR-npc-Karliah_13.jpg"},{"name":"Aela the Huntress","rarity":"epic","id":"aela-the-huntress","subtitle":"Character","details":"Member of the Companions' Circle and a proud werewolf of Hircine, an archery master who can make the Dragonborn a beast as well.","image":"https://images.uesp.net/5/52/SR-npc-Aela_the_Huntress.jpg"},{"name":"Maven Black-Briar","rarity":"epic","id":"maven-black-briar","subtitle":"Character","details":"Matriarch of Riften's Black-Briar mead empire, whose gold and connections to the Guild and Brotherhood make her the city's true ruler.","image":"https://images.uesp.net/0/00/SR-npc-Maven_Black-Briar.jpg"},{"name":"Elisif the Fair","rarity":"epic","id":"elisif-the-fair","subtitle":"Character","details":"Young widowed Jarl of Solitude whose husband, High King Torygg, was killed by Ulfric; the Empire's favored choice for High Queen.","image":"https://images.uesp.net/a/a9/SR-npc-Elisif_the_Fair.jpg"},{"name":"Elenwen","rarity":"epic","id":"elenwen","subtitle":"Character","details":"First Emissary of the Thalmor in Skyrim, who enforces the Talos ban and hosts the diplomatic party the Dragonborn must infiltrate.","image":"https://images.uesp.net/7/7c/SR-npc-Elenwen.jpg"},{"name":"Isran","rarity":"epic","id":"isran","subtitle":"Character","details":"Redguard vampire hunter who rebuilt the Dawnguard in an old fort near Riften after losing his family to the vampires he hunts.","image":"https://images.uesp.net/7/74/SR-npc-Isran.jpg"},{"name":"Valerica","rarity":"epic","id":"valerica","subtitle":"Character","details":"Serana's mother, a pure-blooded vampire who fled to the Soul Cairn with an Elder Scroll to hide from Harkon's obsession.","image":"https://images.uesp.net/c/c7/SR-npc-Valerica.jpg"},{"name":"Neloth","rarity":"epic","id":"neloth","subtitle":"Character","details":"Ageless Telvanni wizard of Solstheim who conducts experiments from his floating mushroom tower, Tel Mithryn, and cares little for casualties.","image":"https://images.uesp.net/f/f8/SR-npc-Neloth2.jpg"},{"name":"Frea","rarity":"epic","id":"frea","subtitle":"Character","details":"Shaman of the Skaal village on Solstheim, a fierce warrior who joins the fight against Miraak's corruption of her people.","image":"https://images.uesp.net/d/d9/SR-npc-Frea.jpg"},{"name":"Savos Aren","rarity":"epic","id":"savos-aren","subtitle":"Character","details":"Dunmer Arch-Mage of the College of Winterhold, haunted by a Labyrinthian expedition that killed every companion he brought with him.","image":"https://images.uesp.net/1/11/SR-npc-Savos_Aren.jpg"},{"name":"Babette","rarity":"epic","id":"babette","subtitle":"Character","details":"A 300-year-old vampire turned as a child, the Dark Brotherhood's alchemist and most disarming assassin in the Falkreath Sanctuary.","image":"https://images.uesp.net/2/20/SR-npc-Babette.jpg"},{"name":"Arch-Curate Vyrthur","rarity":"epic","id":"arch-curate-vyrthur","subtitle":"Character","details":"Last of the Snow Elves, a vampire who corrupted the Chantry of Auri-El to take revenge on the god who abandoned him.","image":"https://images.uesp.net/6/6a/SR-npc-Arch-Curate_Vyrthur.jpg"},{"name":"Knight-Paladin Gelebor","rarity":"epic","id":"knight-paladin-gelebor","subtitle":"Character","details":"The last uncorrupted Snow Elf, guardian of the Chantry of Auri-El, who guards the wayshrine and his fallen brother's memory.","image":"https://images.uesp.net/6/63/SR-npc-Knight-Paladin_Gelebor.jpg"},{"name":"Titus Mede II","rarity":"epic","id":"titus-mede-ii","subtitle":"Character","details":"Emperor of Tamriel who signed the White-Gold Concordat with the Dominion, and the Dark Brotherhood's ultimate assassination contract.","image":"https://images.uesp.net/8/8f/SR-npc-Emperor_Titus_Mede_II.jpg"},{"name":"Teldryn Sero","rarity":"epic","id":"teldryn-sero","subtitle":"Character","details":"Dunmer spellsword for hire in Raven Rock who calls himself the best blade in Morrowind, and fights like he believes it.","image":"https://images.uesp.net/3/32/SR-npc-Teldryn_Sero.jpg"},{"name":"Skjor","rarity":"epic","id":"skjor","subtitle":"Character","details":"Senior member of the Companions' Circle and a werewolf, killed by the Silver Hand while hunting them with the Dragonborn.","image":"https://images.uesp.net/b/bb/SR-npc-Skjor.jpg"},{"name":"Vilkas","rarity":"rare","id":"vilkas","subtitle":"Character","details":"Scholarly twin of the Companions' Circle, a werewolf who questions the beast blood and guards Jorrvaskr's traditions.","image":"https://images.uesp.net/6/60/SR-npc-Vilkas.jpg"},{"name":"Farkas","rarity":"rare","id":"farkas","subtitle":"Character","details":"Good-natured twin of the Companions' Circle, a werewolf heavy in armor and slow to anger, until the fighting starts.","image":"https://images.uesp.net/c/c2/SR-npc-Farkas.jpg"},{"name":"Delvin Mallory","rarity":"rare","id":"delvin-mallory","subtitle":"Character","details":"Veteran Thieves Guild fence and job-giver in the Ragged Flagon, with old ties to the Dark Brotherhood across Skyrim.","image":"https://images.uesp.net/7/73/SR-npc-Delvin_Mallory.jpg"},{"name":"Vex","rarity":"rare","id":"vex","subtitle":"Character","details":"The Thieves Guild's best lockpick and infiltrator, who assigns burglary and shill jobs from the Ragged Flagon.","image":"https://images.uesp.net/4/4d/SR-npc-Vex.jpg"},{"name":"Tolfdir","rarity":"rare","id":"tolfdir","subtitle":"Character","details":"The College of Winterhold's kindly master of Alteration, who teaches the Dragonborn's first lessons and studies the Eye of Magnus.","image":"https://images.uesp.net/3/36/SR-npc-Tolfdir.jpg"},{"name":"Galmar Stone-Fist","rarity":"rare","id":"galmar-stone-fist","subtitle":"Character","details":"Ulfric's housecarl and the Stormcloaks' second-in-command, a blunt old soldier who plans the rebellion's campaigns.","image":"https://images.uesp.net/9/9a/SR-npc-Galmar_Stone-Fist.jpg"},{"name":"Legate Rikke","rarity":"rare","id":"legate-rikke","subtitle":"Character","details":"Chief legate of the Imperial Legion in Skyrim, a Nord torn between her oath to the Empire and love of her homeland.","image":"https://images.uesp.net/b/bf/SR-npc-Legate_Rikke.jpg"},{"name":"Gunmar","rarity":"rare","id":"gunmar","subtitle":"Character","details":"Dawnguard's animal trainer and Isran's old hunting partner, who supplies the fort with armored trolls for the vampire fight.","image":"https://images.uesp.net/4/46/SR-npc-Gunmar.jpg"},{"name":"Sorine Jurard","rarity":"rare","id":"sorine-jurard","subtitle":"Character","details":"Breton engineer recruited by the Dawnguard, whose Dwemer research produces enhanced crossbows and exploding bolts.","image":"https://images.uesp.net/f/f0/SR-npc-Sorine_Jurard.jpg"},{"name":"Storn Crag-Strider","rarity":"rare","id":"storn-crag-strider","subtitle":"Character","details":"Shaman of the Skaal who guards the village's secrets, and gives his life reading a Black Book so the Dragonborn can face Miraak.","image":"https://images.uesp.net/8/8f/SR-npc-Storn_Crag-Strider.jpg"},{"name":"Irileth","rarity":"rare","id":"irileth","subtitle":"Character","details":"Jarl Balgruuf's Dunmer housecarl, a veteran soldier who leads Whiterun's guard against the first dragon at the Western Watchtower.","image":"https://images.uesp.net/b/b7/SR-npc-Irileth.jpg"},{"name":"Nazir","rarity":"rare","id":"nazir","subtitle":"Character","details":"Redguard assassin of the Dark Brotherhood who hands out contracts with dry wit, and one of the Sanctuary's few survivors.","image":"https://images.uesp.net/0/02/SR-npc-Nazir.jpg"},{"name":"Idgrod Ravencrone","rarity":"rare","id":"idgrod-ravencrone","subtitle":"Character","details":"Elderly Jarl of Morthal, a mystic guided by visions who must answer her people's fears of vampires moving into her swamp town.","image":"https://images.uesp.net/4/4a/SR-npc-Idgrod_Ravencrone.jpg"},{"name":"Laila Law-Giver","rarity":"rare","id":"laila-law-giver","subtitle":"Character","details":"Jarl of Riften in name, an honest ruler whose authority is quietly swallowed by Maven Black-Briar's money and influence.","image":"https://images.uesp.net/d/d6/SR-npc-Laila_Law-Giver.jpg"},{"name":"Commander Maro","rarity":"rare","id":"commander-maro","subtitle":"Character","details":"Commander of the Penitus Oculatus in Skyrim, who turns his grief for his murdered son into a vendetta against the Brotherhood.","image":"https://images.uesp.net/7/70/SR-npc-Commander_Maro.jpg"},{"name":"Hadvar","rarity":"rare","id":"hadvar","subtitle":"Character","details":"Imperial soldier who reads the Dragonborn's name at the execution block in Helgen, then helps them escape Alduin's attack.","image":"https://images.uesp.net/a/ae/SR-npc-Hadvar.jpg"},{"name":"Ralof","rarity":"rare","id":"ralof","subtitle":"Character","details":"Stormcloak soldier captured before Helgen, who escapes Alduin's attack alongside the Dragonborn and returns to the rebellion.","image":"https://images.uesp.net/6/6d/SR-npc-Ralof.jpg"},{"name":"Vignar Gray-Mane","rarity":"rare","id":"vignar-gray-mane","subtitle":"Character","details":"Patriarch of Whiterun's Gray-Mane clan and a former Companion, whose family feuds with the Battle-Borns over the civil war.","image":"https://images.uesp.net/b/bc/SR-npc-Vignar_Gray-Mane.jpg"},{"name":"Eorlund Gray-Mane","rarity":"rare","id":"eorlund-gray-mane","subtitle":"Character","details":"Master smith of the Skyforge in Whiterun, widely reckoned the finest blacksmith in Skyrim and maker of legendary steel.","image":"https://images.uesp.net/5/58/SR-npc-Eorlund_Gray-Mane.jpg"},{"name":"Septimus Signus","rarity":"rare","id":"septimus-signus","subtitle":"Character","details":"Brilliant scholar driven mad by an Elder Scroll, exiled to an ice cave where he schemes to open a Dwemer lockbox for Hermaeus Mora.","image":"https://images.uesp.net/1/19/SR-npc-Septimus_Signus.jpg"},{"name":"Madanach","rarity":"rare","id":"madanach","subtitle":"Character","details":"The Forsworn's King in Rags, leader of the rebellion in the Reach, imprisoned for decades in Markarth's Cidhna Mine.","image":"https://images.uesp.net/6/6e/SR-npc-Madanach.jpg"},{"name":"J'zargo","rarity":"rare","id":"jzargo","subtitle":"Character","details":"Ambitious Khajiit apprentice at the College of Winterhold, inventor of flame cloak scrolls and eager to outshine every rival mage.","image":"https://images.uesp.net/0/0e/SR-npc-J%27zargo.jpg"},{"name":"Erik the Slayer","rarity":"uncommon","id":"erik-the-slayer","subtitle":"Character","details":"Rorikstead farmhand who dreams of adventure; based on a real Elder Scrolls fan, Erik West, who died before the game's release.","image":"https://images.uesp.net/f/fe/SR-npc-Erik_the_Slayer.jpg"},{"name":"Jenassa","rarity":"uncommon","id":"jenassa","subtitle":"Character","details":"Dunmer mercenary drinking at Whiterun's Drunken Huntsman, a blade for hire who calls killing an art and herself an artist.","image":"https://images.uesp.net/f/fd/SR-npc-Jenassa.jpg"},{"name":"Jordis the Sword-Maiden","rarity":"uncommon","id":"jordis-the-sword-maiden","subtitle":"Character","details":"Housecarl of Solitude granted to the Dragonborn as Thane of Haafingar, sworn to guard Proudspire Manor and its thane.","image":"https://images.uesp.net/e/e2/SR-npc-Jordis_the_Sword-Maiden.jpg"},{"name":"Brunwulf Free-Winter","rarity":"uncommon","id":"brunwulf-free-winter","subtitle":"Character","details":"Nord veteran in Windhelm who speaks up for the city's Dunmer and Argonians despite his neighbors' old prejudices.","image":"https://images.uesp.net/4/47/SR-npc-Brunwulf_Free-Winter.jpg"},{"name":"Onmund","rarity":"uncommon","id":"onmund","subtitle":"Character","details":"Nord apprentice at the College of Winterhold, studying magic against the wishes of his family back home in the holds.","image":"https://images.uesp.net/1/1a/SR-npc-Onmund.jpg"},{"name":"Brelyna Maryon","rarity":"uncommon","id":"brelyna-maryon","subtitle":"Character","details":"Dunmer apprentice at the College whose experimental practice spells keep turning the Dragonborn green, or into animals.","image":"https://images.uesp.net/b/b9/SR-npc-Brelyna_Maryon.jpg"},{"name":"Erandur","rarity":"uncommon","id":"erandur","subtitle":"Character","details":"Dunmer priest of Mara who once served Vaermina, returning to Nightcaller Temple to destroy the Skull of Corruption he once guarded.","image":"https://images.uesp.net/0/0a/SR-npc-Erandur.jpg"},{"name":"Aranea Ienith","rarity":"uncommon","id":"aranea-ienith","subtitle":"Character","details":"Priestess of Azura tending her mistress's shrine above Winterhold, granted visions of the Dragonborn's coming years in advance.","image":"https://images.uesp.net/3/38/SR-npc-Aranea_Ienith.jpg"},{"name":"Derkeethus","rarity":"uncommon","id":"derkeethus","subtitle":"Character","details":"Argonian miner and follower held captive by Falmer in Darkwater Pass, one of Skyrim's only Argonian companions.","image":"https://images.uesp.net/7/7e/SR-npc-Derkeethus.jpg"},{"name":"Faendal","rarity":"uncommon","id":"faendal","subtitle":"Character","details":"Bosmer archer and lumber worker in Riverwood, locked in a love rivalry with the bard Sven over Camilla Valerius.","image":"https://images.uesp.net/5/5f/SR-npc-Faendal.jpg"},{"name":"Farengar Secret-Fire","rarity":"uncommon","id":"farengar-secret-fire","subtitle":"Character","details":"Whiterun's court wizard in Dragonsreach, who sends the Dragonborn into Bleak Falls Barrow to recover the ancient Dragonstone.","image":"https://images.uesp.net/5/51/SR-npc-Farengar_Secret-Fire.jpg"},{"name":"Sybille Stentor","rarity":"uncommon","id":"sybille-stentor","subtitle":"Character","details":"Court wizard of Solitude's Blue Palace, a vampire who has quietly served the jarls of Haafingar for generations.","image":"https://images.uesp.net/b/b5/SR-npc-Sybille_Stentor_02.jpg"},{"name":"Calcelmo","rarity":"uncommon","id":"calcelmo","subtitle":"Character","details":"Markarth's court wizard and Skyrim's foremost Dwemer scholar, who buys every dwarven artifact the Dragonborn carries in.","image":"https://images.uesp.net/7/7c/SR-npc-Calcelmo.jpg"},{"name":"Wylandriah","rarity":"uncommon","id":"wylandriah","subtitle":"Character","details":"Riften's absent-minded court wizard in Mistveil Keep, forever losing her notes and sending visitors on ingredient errands.","image":"https://images.uesp.net/d/d8/SR-npc-Wylandriah.jpg"},{"name":"Nelacar","rarity":"uncommon","id":"nelacar","subtitle":"Character","details":"Altmer mage who left the College of Winterhold and now studies soul gems from Winterhold's inn, tied to Azura's Star.","image":"https://images.uesp.net/a/a0/SR-npc-Nelacar.jpg"},{"name":"Tonilia","rarity":"uncommon","id":"tonilia","subtitle":"Character","details":"The Thieves Guild's fence and armor merchant in the Ragged Flagon, who upgrades the Guild armor of new recruits.","image":"https://images.uesp.net/8/80/SR-npc-Tonilia.jpg"},{"name":"Sapphire","rarity":"uncommon","id":"sapphire","subtitle":"Character","details":"Thieves Guild operative in Riften with a guarded past, whose real name and history she keeps from everyone in the Flagon.","image":"https://images.uesp.net/c/c3/SR-npc-Sapphire.jpg"},{"name":"Njada Stonearm","rarity":"uncommon","id":"njada-stonearm","subtitle":"Character","details":"Sharp-tongued shield-sister of the Companions, a master of the block who greets new blood in Jorrvaskr with open contempt.","image":"https://images.uesp.net/e/e0/SR-npc-Njada_Stonearm.jpg"},{"name":"Nazeem","rarity":"uncommon","id":"nazeem","subtitle":"Character","details":"Wealthy Redguard farm owner in Whiterun, infamous for asking visitors whether they get to the Cloud District very often.","image":"https://images.uesp.net/3/30/SR-npc-Nazeem.jpg"},{"name":"Saadia","rarity":"uncommon","id":"saadia","subtitle":"Character","details":"Redguard fugitive waiting tables at the Bannered Mare, hunted by Alik'r warriors for a betrayal she denies ever committing.","image":"https://images.uesp.net/6/67/SR-npc-Saadia.jpg"},{"name":"Falion","rarity":"uncommon","id":"falion","subtitle":"Character","details":"Morthal's master of Conjuration, a scholar of vampirism who knows the ritual to cure the Dragonborn of the condition.","image":"https://images.uesp.net/5/50/SR-npc-Falion.jpg"},{"name":"Valdimar","rarity":"uncommon","id":"valdimar","subtitle":"Character","details":"Nord housecarl granted with Windstad Manor in Hjaalmarch, a battle-mage sworn to guard the Dragonborn's marshland estate.","image":"https://images.uesp.net/d/de/SR-npc-Valdimar.jpg"},{"name":"Illia","rarity":"uncommon","id":"illia","subtitle":"Character","details":"Imperial witch raised in Darklight Tower's coven, who turns against her own mother to stop a ritual of Hagravens.","image":"https://images.uesp.net/6/6f/SR-npc-Illia.jpg"},{"name":"Eola","rarity":"uncommon","id":"eola","subtitle":"Character","details":"Devotee of Namira who leads a coven of cannibals in Markarth's Hall of the Dead and invites the Dragonborn to the feast.","image":"https://images.uesp.net/0/06/SR-npc-Eola.jpg"},{"name":"Heimskr","rarity":"uncommon","id":"heimskr","subtitle":"Character","details":"Thunderous priest of Talos preaching in Whiterun's Wind District, defying the Thalmor's ban for all the city to hear.","image":"https://images.uesp.net/6/6c/SR-npc-Heimskr.jpg"},{"name":"Sven","rarity":"common","id":"sven","subtitle":"Character","details":"Riverwood's resident bard and lumber worker, who schemes with forged letters to win Camilla Valerius from his rival Faendal.","image":"https://images.uesp.net/6/64/SR-npc-Sven.jpg"},{"name":"Camilla Valerius","rarity":"common","id":"camilla-valerius","subtitle":"Character","details":"Sister of the Riverwood Trader's owner, courted by both Sven and Faendal in the village's small-town love triangle.","image":"https://images.uesp.net/d/dc/SR-npc-Camilla_Valerius.jpg"},{"name":"Lucan Valerius","rarity":"common","id":"lucan-valerius","subtitle":"Character","details":"Owner of the Riverwood Trader, whose stolen golden claw sends the Dragonborn into Bleak Falls Barrow for the first time.","image":"https://images.uesp.net/0/0f/SR-npc-Lucan_Valerius.jpg"},{"name":"Belethor","rarity":"common","id":"belethor","subtitle":"Character","details":"Breton owner of Whiterun's general goods store, who cheerfully claims he would buy your relatives if you were selling.","image":"https://images.uesp.net/8/87/SR-npc-Belethor.jpg"},{"name":"Ysolda","rarity":"common","id":"ysolda","subtitle":"Character","details":"Whiterun market trader learning the merchant's craft from the Khajiit caravans, saving to buy the Bannered Mare one day.","image":"https://images.uesp.net/3/3f/SR-npc-Ysolda.jpg"},{"name":"Mikael","rarity":"common","id":"mikael","subtitle":"Character","details":"Bard at the Bannered Mare whose harassing of Carlotta Valentia makes him the target of a very persuasive conversation.","image":"https://images.uesp.net/b/b9/SR-npc-Mikael.jpg"},{"name":"Adrianne Avenicci","rarity":"common","id":"adrianne-avenicci","subtitle":"Character","details":"Blacksmith of Warmaiden's in Whiterun, daughter of the jarl's steward, determined to out-forge her father's legacy.","image":"https://images.uesp.net/3/36/SR-npc-Adrianne_Avenicci.jpg"},{"name":"Arcadia","rarity":"common","id":"arcadia","subtitle":"Character","details":"Imperial alchemist of Whiterun whose shop, Arcadia's Cauldron, comes with a fresh diagnosis for every customer who enters.","image":"https://images.uesp.net/5/58/SR-npc-Arcadia.jpg"},{"name":"Jon Battle-Born","rarity":"common","id":"jon-battle-born","subtitle":"Character","details":"Scion of Whiterun's Battle-Born clan, secretly in love with Olfina Gray-Mane of his family's oldest rivals, despite the feud.","image":"https://images.uesp.net/0/00/SR-npc-Jon_Battle-Born.jpg"},{"name":"Alvor","rarity":"common","id":"alvor","subtitle":"Character","details":"Riverwood's blacksmith and Hadvar's uncle, the first friendly face many Dragonborn meet after escaping Helgen's destruction.","image":"https://images.uesp.net/c/c6/SR-npc-Alvor.jpg"},{"name":"Gerdur","rarity":"common","id":"gerdur","subtitle":"Character","details":"Owner of Riverwood's lumber mill and sister of Ralof, who points the Dragonborn toward Jarl Balgruuf with news of the dragons.","image":"https://images.uesp.net/d/de/SR-npc-Gerdur.jpg"},{"name":"Carlotta Valentia","rarity":"common","id":"carlotta-valentia","subtitle":"Character","details":"Whiterun market vendor and widowed mother, a hard-working produce seller fending off the bard Mikael's unwanted advances.","image":"https://images.uesp.net/7/70/SR-npc-Carlotta_Valentia.jpg"},{"name":"Amren","rarity":"common","id":"amren","subtitle":"Character","details":"Redguard sellsword in Whiterun searching for his father's stolen sword, taken by bandits to a hideout in the hold.","image":"https://images.uesp.net/b/bc/SR-npc-Amren.jpg"},{"name":"Noster Eagle-Eye","rarity":"common","id":"noster-eagle-eye","subtitle":"Character","details":"One-eyed Imperial beggar in Solitude, a forgotten veteran of the Great War who lost everything but his scavenger's eye.","image":"https://images.uesp.net/4/43/SR-npc-Noster_Eagle-Eye.jpg"},{"name":"Silda the Unseen","rarity":"common","id":"silda-the-unseen","subtitle":"Character","details":"Pickpocket trainer and beggar in Windhelm, warming her hands at graveyard fires in the city's coldest corners.","image":"https://images.uesp.net/4/47/SR-npc-Silda_the_Unseen.jpg"},{"name":"Brenuin","rarity":"common","id":"brenuin","subtitle":"Character","details":"Whiterun's cheerful town drunk, an Argonian forever cadging a few septims toward his next bottle of mead at the Mare.","image":"https://images.uesp.net/4/4a/SR-npc-Brenuin.jpg"},{"name":"Susanna the Wicked","rarity":"common","id":"susanna-the-wicked","subtitle":"Character","details":"Barmaid at Windhelm's Candlehearth Hall whose murder by the Butcher opens the investigation into the city's killings.","image":"https://images.uesp.net/3/37/SR-npc-Susanna_the_Wicked.jpg"},{"name":"Calixto Corrium","rarity":"common","id":"calixto-corrium","subtitle":"Character","details":"Owner of Windhelm's House of Curiosities, revealed as the Butcher murdering women to resurrect his dead sister.","image":"https://images.uesp.net/8/8e/SR-npc-Calixto_Corrium.jpg"},{"name":"Athis","rarity":"common","id":"athis","subtitle":"Character","details":"Dunmer recruit of the Companions and expert one-handed trainer, proving himself among the warriors of Jorrvaskr.","image":"https://images.uesp.net/3/3b/SR-npc-Athis.jpg"},{"name":"Lob","rarity":"common","id":"lob","subtitle":"Character","details":"Orc follower from Largashbur stronghold in the Rift, one of the stronghold orcs willing to leave the gates and adventure.","image":"https://images.uesp.net/e/e2/SR-npc-Lob.jpg"},{"name":"Gregor","rarity":"common","id":"gregor","subtitle":"Character","details":"Nord housecarl granted with Heljarchen Hall in the Pale, sworn to guard the Dragonborn's northern homestead and everyone in it.","image":"https://images.uesp.net/4/4a/SR-npc-Gregor.jpg"},{"name":"Kematu","rarity":"common","id":"kematu","subtitle":"Character","details":"Leader of the Alik'r warriors hunting the fugitive Saadia across Skyrim, waiting in Swindler's Den to tell his side.","image":"https://images.uesp.net/a/ac/SR-npc-Kematu.jpg"},{"name":"Annekke Crag-Jumper","rarity":"common","id":"annekke-crag-jumper","subtitle":"Character","details":"Owner of the mine at Darkwater Crossing and a former adventurer, an archer follower who still misses the road.","image":"https://images.uesp.net/1/10/SR-npc-Annekke_Crag-Jumper.jpg"},{"name":"Ghorbash the Iron Hand","rarity":"common","id":"ghorbash-the-iron-hand","subtitle":"Character","details":"Orc follower from Dushnikh Yal stronghold, a former Imperial Legionary who left the stronghold life behind once before.","image":"https://images.uesp.net/a/a8/SR-npc-Ghorbash_the_Iron_Hand.jpg"},{"name":"Borgakh the Steel Heart","rarity":"common","id":"borgakh-the-steel-heart","subtitle":"Character","details":"Orc follower from Mor Khazgur stronghold, seeking to escape the arranged marriage to a chieftain that awaits her.","image":"https://images.uesp.net/f/ff/SR-npc-Borgakh_the_Steel_Heart.jpg"},{"name":"Cosnach","rarity":"common","id":"cosnach","subtitle":"Character","details":"Breton mercenary drinking away his wages at Markarth's Silver-Blood Inn, happy to brawl or follow for the right coin.","image":"https://images.uesp.net/4/45/SR-npc-Cosnach.jpg"},{"name":"Belrand","rarity":"common","id":"belrand","subtitle":"Character","details":"Nord spellsword for hire in Windhelm's Candlehearth Hall, a mercenary who wields blade and spell in equal measure.","image":"https://images.uesp.net/5/52/SR-npc-Belrand.jpg"},{"name":"Ahtar","rarity":"common","id":"ahtar","subtitle":"Character","details":"Redguard headsman of Solitude, the city's executioner, who asks the Dragonborn to finish off an escaped bandit leader.","image":"https://images.uesp.net/2/29/SR-npc-Ahtar.jpg"},{"name":"Rayya","rarity":"common","id":"rayya","subtitle":"Character","details":"Redguard housecarl granted with Lakeview Manor in Falkreath, a dual-wielding warrior sworn to guard the homestead.","image":"https://images.uesp.net/b/be/SR-npc-Rayya.jpg"},{"name":"Orgnar","rarity":"common","id":"orgnar","subtitle":"Character","details":"Bartender of the Sleeping Giant Inn in Riverwood, employee of Delphine who hears every traveler's story over the counter.","image":"https://images.uesp.net/0/0d/SR-npc-Orgnar.jpg"},{"name":"Whiterun","rarity":"chase","id":"whiterun","subtitle":"Location","details":"The first great city most Dragonborn reach, a walled hold capital on the central tundra where Jarl Balgruuf rules from Dragonsreach.","image":"https://images.uesp.net/f/f5/SR-place-Whiterun.jpg"},{"name":"High Hrothgar","rarity":"legendary","id":"high-hrothgar","subtitle":"Location","details":"The Greybeards' monastery high on the Throat of the World, reached by the Seven Thousand Steps and guarded by frost trolls.","image":"https://images.uesp.net/5/50/SR-place-High_Hrothgar.jpg"},{"name":"Sovngarde","rarity":"legendary","id":"sovngarde","subtitle":"Location","details":"The Nord afterlife, a mist-shrouded hall-world where heroes feast in the Hall of Valor and Alduin lurks to feed on souls.","image":"https://images.uesp.net/7/76/SR-place-Sovngarde.jpg"},{"name":"Solitude","rarity":"legendary","id":"solitude","subtitle":"Location","details":"Capital of Skyrim and its richest port, perched on a great rock arch above the Sea of Ghosts, seat of the East Empire Company.","image":"https://images.uesp.net/6/69/SR-place-Solitude.jpg"},{"name":"The Throat of the World","rarity":"legendary","id":"the-throat-of-the-world","subtitle":"Location","details":"Skyrim's highest peak, sacred to the Greybeards, where Paarthurnax meditates above a swirling time-wound at the summit.","image":"https://images.uesp.net/5/55/SR-place-Throat_of_the_World.jpg"},{"name":"Raven Rock","rarity":"legendary","id":"raven-rock","subtitle":"Location","details":"An ebony-mining town on Solstheim's ash coast, governed by House Redoran councilor Lleril Morvayn behind its Bulwark walls.","image":"https://images.uesp.net/4/43/SR-place-Raven_Rock.jpg"},{"name":"Castle Volkihar","rarity":"legendary","id":"castle-volkihar","subtitle":"Location","details":"Lord Harkon's island fortress off the haunted northern coast, home to the ancient Volkihar vampire clan and its court.","image":"https://images.uesp.net/4/42/SR-place-Castle_Volkihar.jpg"},{"name":"Markarth","rarity":"epic","id":"markarth","subtitle":"Location","details":"A city carved into Dwemer stone in the Reach, ruled by the corrupt Silver-Bloods and haunted by Forsworn conspiracy.","image":"https://images.uesp.net/2/28/SR-place-Markarth.jpg"},{"name":"Riften","rarity":"epic","id":"riften","subtitle":"Location","details":"The Rift's canal city of smugglers and thieves, where the Black-Briar family and the Thieves Guild pull every string.","image":"https://images.uesp.net/a/ad/SR-place-Riften.jpg"},{"name":"Windhelm","rarity":"epic","id":"windhelm","subtitle":"Location","details":"Skyrim's oldest city and the storm-cloaked capital of Ulfric's rebellion, built of stone in Eastmarch's frozen north.","image":"https://images.uesp.net/b/b7/SR-place-Windhelm.jpg"},{"name":"Blackreach","rarity":"epic","id":"blackreach","subtitle":"Location","details":"An immense glowing cavern beneath Skyrim, lit by giant mushrooms, where Dwemer ruins and Falmer camps sprawl for miles.","image":"https://images.uesp.net/0/00/SR-place-Blackreach.jpg"},{"name":"Skuldafn","rarity":"epic","id":"skuldafn","subtitle":"Location","details":"An ancient Nord temple in the Velothi Mountains where the dragon priest Nahkriin guards Alduin's portal to Sovngarde.","image":"https://images.uesp.net/2/25/SR-place-Skuldafn_Temple.jpg"},{"name":"Forgotten Vale","rarity":"epic","id":"forgotten-vale","subtitle":"Location","details":"A hidden glacial valley where the last Snow Elves sheltered, holding Auriel's Bow beyond the wayshrines of the Chantry.","image":"https://images.uesp.net/d/d9/SR-place-Forgotten_Vale.jpg"},{"name":"Soul Cairn","rarity":"epic","id":"soul-cairn","subtitle":"Location","details":"An Oblivion plane of jagged crystals and restless undead, ruled by the Ideal Masters who bargain for mortal souls.","image":"https://images.uesp.net/5/54/SR-place-Soul_Cairn.jpg"},{"name":"Apocrypha","rarity":"epic","id":"apocrypha","subtitle":"Location","details":"Hermaeus Mora's Daedric realm, an endless library of black tomes and tentacles where forbidden knowledge drives men mad.","image":"https://images.uesp.net/6/6e/SR-place-Apocrypha.jpg"},{"name":"Dragonsreach","rarity":"epic","id":"dragonsreach","subtitle":"Location","details":"Jarl Balgruuf's great hall in Whiterun, built centuries ago to imprison the dragon Numinex, whose skull still watches the throne.","image":"https://images.uesp.net/0/0e/SR-place-Dragonsreach.jpg"},{"name":"Sky Haven Temple","rarity":"epic","id":"sky-haven-temple","subtitle":"Location","details":"A hidden Akaviri fortress in the Reach where the Blades recorded prophecy on Alduin's Wall, carved into the mountainside.","image":"https://images.uesp.net/f/f3/SR-place-Sky_Haven_Temple_Exterior.jpg"},{"name":"Dawnstar","rarity":"rare","id":"dawnstar","subtitle":"Location","details":"The Pale's northern port, a mining and fishing town tormented by a Daedric nightmare curse draining its people's sleep.","image":"https://images.uesp.net/1/1b/SR-place-Dawnstar.jpg"},{"name":"Falkreath","rarity":"rare","id":"falkreath","subtitle":"Location","details":"A hold capital wrapped in pine forest, famed for Skyrim's largest cemetery, filled by centuries of war and wild beasts.","image":"https://images.uesp.net/6/6a/SR-place-Falkreath.jpg"},{"name":"Morthal","rarity":"rare","id":"morthal","subtitle":"Location","details":"Hjaalmarch's quiet marsh capital, a misty town of alchemists and wary folk, forever shadowed by vampire rumours.","image":"https://images.uesp.net/c/cc/SR-place-Morthal.jpg"},{"name":"Winterhold","rarity":"rare","id":"winterhold","subtitle":"Location","details":"A shattered hold capital clinging to a cliff edge, most of it lost to the sea in the Great Collapse generations ago.","image":"https://images.uesp.net/7/72/SR-place-Winterhold.jpg"},{"name":"Bleak Falls Barrow","rarity":"rare","id":"bleak-falls-barrow","subtitle":"Location","details":"A draugr-haunted barrow above Riverwood where the Dragonstone waits, guarded by traps, spiders and a restless overlord.","image":"https://images.uesp.net/1/1f/SR-place-Bleak_Falls_Barrow.jpg"},{"name":"Labyrinthian","rarity":"rare","id":"labyrinthian","subtitle":"Location","details":"A ruined dragon-cult city in Hjaalmarch's mountains, its maze raised over the streets of Bromjunaar, the priests' capital.","image":"https://images.uesp.net/9/99/SR-place-Labyrinthian.jpg"},{"name":"Fort Dawnguard","rarity":"rare","id":"fort-dawnguard","subtitle":"Location","details":"The Dawnguard's hidden fortress deep in Dayspring Canyon, rebuilt by Isran to destroy the vampire threat returning to Skyrim.","image":"https://images.uesp.net/5/53/SR-place-Fort_Dawnguard.jpg"},{"name":"Dayspring Canyon","rarity":"rare","id":"dayspring-canyon","subtitle":"Location","details":"A secluded canyon east of Riften, thick with pines and geysers, concealing the only path through to Fort Dawnguard.","image":"https://images.uesp.net/3/32/SR-place-Dayspring_Canyon.jpg"},{"name":"Irkngthand","rarity":"rare","id":"irkngthand","subtitle":"Location","details":"A flooded Dwemer ruin in the Pale where Nightingales hunt Karliah among traps guarding the Eyes of the Falmer.","image":"https://images.uesp.net/5/5c/SR-place-Irkngthand_03.jpg"},{"name":"Saarthal","rarity":"rare","id":"saarthal","subtitle":"Location","details":"The buried first city of men in Skyrim, excavated by the College of Winterhold, where the Eye of Magnus was unearthed.","image":"https://images.uesp.net/5/5d/SR-place-Saarthal.jpg"},{"name":"Ustengrav","rarity":"rare","id":"ustengrav","subtitle":"Location","details":"The tomb of Jurgen Windcaller, founder of the Way of the Voice, where thieves race the Dragonborn to his horn's resting place.","image":"https://images.uesp.net/a/aa/SR-place-Ustengrav.jpg"},{"name":"Temple of Miraak","rarity":"rare","id":"temple-of-miraak","subtitle":"Location","details":"A Solstheim temple wrapped around the Tree Stone, built by enthralled cultists toiling day and night for the first Dragonborn.","image":"https://images.uesp.net/e/e2/SR-place-Temple_of_Miraak.jpg"},{"name":"Dimhollow Crypt","rarity":"rare","id":"dimhollow-crypt","subtitle":"Location","details":"A vampire tomb in the Pale where Serana sleeps sealed in a monolith, clutching an Elder Scroll through the centuries.","image":"https://images.uesp.net/6/62/SR-place-Dimhollow_Crypt.jpg"},{"name":"Nightingale Hall","rarity":"rare","id":"nightingale-hall","subtitle":"Location","details":"The Nightingales' secret hall beneath the hills near Riften, restored for Nocturnal's chosen trinity of thieves.","image":"https://images.uesp.net/5/56/SR-place-Nightingale_Hall.jpg"},{"name":"Eldergleam Sanctuary","rarity":"rare","id":"eldergleam-sanctuary","subtitle":"Location","details":"A sacred grotto in Eastmarch's hot springs, home to the Eldergleam, an ancient parent tree sacred to Kynareth.","image":"https://images.uesp.net/2/2a/SR-place-Eldergleam_Sanctuary.jpg"},{"name":"Riverwood","rarity":"uncommon","id":"riverwood","subtitle":"Location","details":"A small lumber village on the White River beneath Bleak Falls Barrow, the first friendly stop after escaping Helgen.","image":"https://images.uesp.net/5/5f/SR-place-Riverwood.jpg"},{"name":"Rorikstead","rarity":"uncommon","id":"rorikstead","subtitle":"Location","details":"A Whiterun Hold farming village of mysteriously rich harvests, named for the veteran Rorik who bought its land.","image":"https://images.uesp.net/9/96/SR-place-Rorikstead.jpg"},{"name":"Ivarstead","rarity":"uncommon","id":"ivarstead","subtitle":"Location","details":"A village in the Rift at the foot of the Throat of the World, where pilgrims begin climbing the Seven Thousand Steps.","image":"https://images.uesp.net/c/ca/SR-place-Ivarstead.jpg"},{"name":"Dragon Bridge","rarity":"uncommon","id":"dragon-bridge","subtitle":"Location","details":"A Haafingar village named for the great stone bridge carved with dragon heads that spans the Karth River north.","image":"https://images.uesp.net/1/14/SR-place-Dragon_Bridge.jpg"},{"name":"Karthwasten","rarity":"uncommon","id":"karthwasten","subtitle":"Location","details":"A Reach mining village with poor silver veins, caught between the Silver-Blood family and its own stubborn Nord owners.","image":"https://images.uesp.net/a/a4/SR-place-Karthwasten.jpg"},{"name":"Shor's Stone","rarity":"uncommon","id":"shors-stone","subtitle":"Location","details":"A small Rift mining village named for Shor, god of men, where ebony ore feeds its forge and bears stalk its woods.","image":"https://images.uesp.net/7/70/SR-place-Shor%27s_Stone.jpg"},{"name":"Kynesgrove","rarity":"uncommon","id":"kynesgrove","subtitle":"Location","details":"An Eastmarch village built around a sacred grove of Kyne, where a dragon's burial mound rises just beyond the inn.","image":"https://images.uesp.net/f/fb/SR-place-Kynesgrove.jpg"},{"name":"Helgen","rarity":"uncommon","id":"helgen","subtitle":"Location","details":"A border town in Falkreath Hold destroyed when Alduin attacked during an Imperial execution, the Dragonborn's among them.","image":"https://images.uesp.net/5/51/SR-place-Helgen_02.jpg"},{"name":"Skaal Village","rarity":"uncommon","id":"skaal-village","subtitle":"Location","details":"An isolated village in Solstheim's frozen north, home to the Skaal, who worship the All-Maker and shun Daedric power.","image":"https://images.uesp.net/5/55/SR-place-Skaal_Village.jpg"},{"name":"Thirsk Mead Hall","rarity":"uncommon","id":"thirsk-mead-hall","subtitle":"Location","details":"A Solstheim mead hall of Nord warriors on Lake Fjalding, once seized by riekling squatters claiming it as their own.","image":"https://images.uesp.net/5/53/SR-place-Thirsk_Mead_Hall_02.jpg"},{"name":"Tel Mithryn","rarity":"uncommon","id":"tel-mithryn","subtitle":"Location","details":"The fungal tower on Solstheim's coast where the Telvanni wizard Neloth conducts experiments with his long-suffering staff.","image":"https://images.uesp.net/b/b8/SR-place-Tel_Mithryn.jpg"},{"name":"Nightgate Inn","rarity":"uncommon","id":"nightgate-inn","subtitle":"Location","details":"A lonely inn on the Pale's border road, kept by Hadring, where travellers swap rumours far from any city's walls.","image":"https://images.uesp.net/a/a5/SR-place-Nightgate_Inn.jpg"},{"name":"Dustman's Cairn","rarity":"uncommon","id":"dustmans-cairn","subtitle":"Location","details":"An ancient Nord tomb west of Whiterun where a Companions errand becomes an ambush by the Silver Hand werewolf hunters.","image":"https://images.uesp.net/1/14/SR-place-Dustman%27s_Cairn.jpg"},{"name":"Shroud Hearth Barrow","rarity":"uncommon","id":"shroud-hearth-barrow","subtitle":"Location","details":"A haunted tomb outside Ivarstead, rigged with traps by a fraud alchemist posing as the ghost of a buried warlord.","image":"https://images.uesp.net/5/54/SR-place-Shroud_Hearth_Barrow.jpg"},{"name":"Valthume","rarity":"uncommon","id":"valthume","subtitle":"Location","details":"A dragon priest's tomb in the Reach's hills, sealed by the ghost Valdar to keep Hevnoraak's evil bottled forever.","image":"https://images.uesp.net/f/f0/SR-place-Valthume.jpg"},{"name":"Forelhost","rarity":"uncommon","id":"forelhost","subtitle":"Location","details":"A dragon cult temple above Riften where Rahgot's followers chose poison over surrender at the cult's bitter end.","image":"https://images.uesp.net/1/13/SR-place-Forelhost.jpg"},{"name":"Volunruud","rarity":"uncommon","id":"volunruud","subtitle":"Location","details":"An ancient tomb in the Pale where a contract to assassinate the Emperor himself is delivered to the Dark Brotherhood.","image":"https://images.uesp.net/2/2a/SR-place-Volunruud.jpg"},{"name":"Korvanjund","rarity":"uncommon","id":"korvanjund","subtitle":"Location","details":"The burial tomb of King Borgas in the Pale's hills, fought over by Legion and Stormcloaks hunting the Jagged Crown.","image":"https://images.uesp.net/4/42/SR-place-Korvanjund.jpg"},{"name":"Fort Frostmoth","rarity":"uncommon","id":"fort-frostmoth","subtitle":"Location","details":"A ruined Imperial fort on Solstheim's southern coast, destroyed by ash spawn raised from General Carius's own garrison.","image":"https://images.uesp.net/3/3d/SR-place-Fort_Frostmoth.jpg"},{"name":"Abandoned Shack","rarity":"uncommon","id":"abandoned-shack","subtitle":"Location","details":"A remote shack in Hjaalmarch's marsh where the Dragonborn wakes bound before Astrid and three hooded captives.","image":"https://images.uesp.net/5/56/SR-place-Abandoned_Shack.jpg"},{"name":"Breezehome","rarity":"common","id":"breezehome","subtitle":"Location","details":"A modest house beside Warmaiden's in Whiterun, the first home most Dragonborn buy, watched over by housecarl Lydia.","image":"https://images.uesp.net/d/d0/SR-place-Breezehome.jpg"},{"name":"Honeyside","rarity":"common","id":"honeyside","subtitle":"Location","details":"A buyable house in Riften with a porch over the canal, honey-seller neighbours and the city's markets at its door.","image":"https://images.uesp.net/3/31/SR-place-Honeyside.jpg"},{"name":"Vlindrel Hall","rarity":"common","id":"vlindrel-hall","subtitle":"Location","details":"A stone hall carved high into Markarth's mountainside, sold only to those who earn the Jarl of the Reach's favour.","image":"https://images.uesp.net/4/49/SR-place-Vlindrel_Hall.jpg"},{"name":"Hjerim","rarity":"common","id":"hjerim","subtitle":"Location","details":"A large Windhelm house once hiding a necromancer murderer, its secret altar room concealed behind a false wardrobe panel.","image":"https://images.uesp.net/f/f5/SR-place-Hjerim.jpg"},{"name":"Proudspire Manor","rarity":"common","id":"proudspire-manor","subtitle":"Location","details":"Solitude's grand three-storey manor, the most expensive house in Skyrim, standing near the Blue Palace and the bards.","image":"https://images.uesp.net/1/19/SR-place-Proudspire_Manor.jpg"},{"name":"Lakeview Manor","rarity":"common","id":"lakeview-manor","subtitle":"Location","details":"A buildable homestead on Falkreath's pine-forested lake shore, where the Dragonborn can raise halls, gardens and family.","image":"https://images.uesp.net/1/1d/SR-place-Lakeview_Manor_13.jpg"},{"name":"Windstad Manor","rarity":"common","id":"windstad-manor","subtitle":"Location","details":"A buildable homestead on Hjaalmarch's marshy coast, the only house in Skyrim with its own fish hatchery by the sea.","image":"https://images.uesp.net/8/8c/SR-place-Windstad_Manor.jpg"},{"name":"Heljarchen Hall","rarity":"common","id":"heljarchen-hall","subtitle":"Location","details":"A buildable homestead on the Pale's tundra near Whiterun's border, beneath the northern lights and giant country.","image":"https://images.uesp.net/5/50/SR-place-Heljarchen_Hall.jpg"},{"name":"Largashbur","rarity":"common","id":"largashbur","subtitle":"Location","details":"An orc stronghold in the Rift whose chieftain is cursed by Malacath, its tribe weakened by giant attacks and shame.","image":"https://images.uesp.net/8/8c/SR-place-Largashbur.jpg"},{"name":"Dushnikh Yal","rarity":"common","id":"dushnikh-yal","subtitle":"Location","details":"An orc stronghold and mine in the Reach, one of the strongest of Skyrim's Orsimer tribes, ruled by Chief Burguk.","image":"https://images.uesp.net/5/5a/SR-place-Dushnikh_Yal.jpg"},{"name":"Mor Khazgur","rarity":"common","id":"mor-khazgur","subtitle":"Location","details":"A remote orc stronghold at the Reach's western edge, guarding an orichalcum mine at the end of a mountain road.","image":"https://images.uesp.net/6/66/SR-place-Mor_Khazgur.jpg"},{"name":"Narzulbur","rarity":"common","id":"narzulbur","subtitle":"Location","details":"An orc stronghold in Eastmarch beside the ebony-rich Gloombound Mine, ruled by the iron hand of Chief Mauhulakh.","image":"https://images.uesp.net/9/91/SR-place-Narzulbur.jpg"},{"name":"Stonehills","rarity":"common","id":"stonehills","subtitle":"Location","details":"A tiny mining settlement in Hjaalmarch serving Rockwallow Mine, little more than a house and a smelter in the marsh.","image":"https://images.uesp.net/c/c8/SR-place-Stonehills.jpg"},{"name":"Embershard Mine","rarity":"common","id":"embershard-mine","subtitle":"Location","details":"A bandit-held iron mine on the forest road near Riverwood, often the first dungeon a new Dragonborn clears in Skyrim.","image":"https://images.uesp.net/5/52/SR-place-Embershard_Mine.jpg"},{"name":"Halted Stream Camp","rarity":"common","id":"halted-stream-camp","subtitle":"Location","details":"A poacher camp north of Whiterun built around a mammoth pit, where bandits butcher giants' herds for tusks and cheese.","image":"https://images.uesp.net/d/d0/SR-place-Halted_Stream_Camp.jpg"},{"name":"White River Watch","rarity":"common","id":"white-river-watch","subtitle":"Location","details":"A bandit cave in a rocky overlook above the White River near Whiterun, led by the nearly blind Hajvarr Iron-Hand.","image":"https://images.uesp.net/b/b9/SR-place-White_River_Watch.jpg"},{"name":"Valtheim Towers","rarity":"common","id":"valtheim-towers","subtitle":"Location","details":"Twin bandit towers straddling the White River on the road to Ivarstead, charging a toll to travellers — or else.","image":"https://images.uesp.net/6/62/SR-place-Valtheim_Towers.jpg"},{"name":"Robber's Gorge","rarity":"common","id":"robbers-gorge","subtitle":"Location","details":"A bandit toll camp blocking the western road through Hjaalmarch's pines, its log traps poised above the mountain pass.","image":"https://images.uesp.net/b/b5/SR-place-Robber%27s_Gorge.jpg"},{"name":"Knifepoint Ridge","rarity":"common","id":"knifepoint-ridge","subtitle":"Location","details":"A bandit mine camp in Falkreath's southern hills, built over a corundum mine and a Boethiah cult's dark errand.","image":"https://images.uesp.net/a/a0/SR-place-Knifepoint_Ridge.jpg"},{"name":"Sleeping Tree Camp","rarity":"common","id":"sleeping-tree-camp","subtitle":"Location","details":"A giant camp west of Whiterun centred on a strange tree whose luminous sap fetches a high price with alchemists.","image":"https://images.uesp.net/3/3b/SR-place-Sleeping_Tree_Camp.jpg"},{"name":"Secunda's Kiss","rarity":"common","id":"secundas-kiss","subtitle":"Location","details":"A giant camp in Whiterun Hold named for the smaller moon Secunda, where mammoths graze beneath standing stones.","image":"https://images.uesp.net/c/cf/SR-place-Secunda%27s_Kiss.jpg"},{"name":"Blizzard Rest","rarity":"common","id":"blizzard-rest","subtitle":"Location","details":"A giant camp on the tundra road between Whiterun and Dawnstar, marked by a mammoth graveyard and painted rocks.","image":"https://images.uesp.net/2/2b/SR-place-Blizzard_Rest.jpg"},{"name":"Talking Stone Camp","rarity":"common","id":"talking-stone-camp","subtitle":"Location","details":"A giant camp in Hjaalmarch beneath a striking overhanging rock formation, its painted boulders resembling a face.","image":"https://images.uesp.net/5/5e/SR-place-Talking_Stone_Camp.jpg"},{"name":"Alduin","rarity":"chase","id":"alduin","subtitle":"Creature","details":"The first-born of Akatosh and the World-Eater of Nord legend, a black dragon prophesied to devour the world at time's end.","image":"https://images.uesp.net/5/54/SR-creature-Alduin.jpg"},{"name":"Paarthurnax","rarity":"chase","id":"paarthurnax","subtitle":"Creature","details":"An ancient dragon who overcame his cruel nature through meditation, leading the Greybeards atop the Throat of the World.","image":"https://images.uesp.net/1/1f/SR-creature-Paarthurnax.jpg"},{"name":"Odahviing","rarity":"legendary","id":"odahviing","subtitle":"Creature","details":"A red dragon in Alduin's service who is trapped at Dragonsreach and bargains his freedom for aid against his master.","image":"https://images.uesp.net/c/c1/SR-creature-Odahviing_02.jpg"},{"name":"Durnehviir","rarity":"legendary","id":"durnehviir","subtitle":"Creature","details":"An undead dragon bound to the Soul Cairn by the Ideal Masters, who teaches the Dragonborn the Soul Tear shout.","image":"https://images.uesp.net/3/37/SR-creature-Durnehviir.jpg"},{"name":"Numinex","rarity":"legendary","id":"numinex","subtitle":"Creature","details":"A dragon from the Merethic Era, captured and caged in Dragonsreach by King Olaf One-Eye after their legendary duel.","image":"https://images.uesp.net/d/d3/SR-creature-Numinex.jpg"},{"name":"Sahrotaar","rarity":"legendary","id":"sahrotaar","subtitle":"Creature","details":"A serpentine dragon enslaved by Miraak in Apocrypha, forced to carry the Dragonborn through its black, book-lined skies.","image":"https://images.uesp.net/5/5e/SR-creature-Sahrotaar.jpg"},{"name":"Morokei","rarity":"epic","id":"morokei","subtitle":"Creature","details":"A dragon priest entombed in Labyrinthian, holding the Staff of Magnus, guarded by two mages enslaved to his will.","image":"https://images.uesp.net/c/c8/SR-creature-Morokei.jpg"},{"name":"Nahkriin","rarity":"epic","id":"nahkriin","subtitle":"Creature","details":"A dragon priest guarding the portal to Sovngarde at Skuldafn, whose mask unlocks the way to Alduin's final battle.","image":"https://images.uesp.net/c/cc/SR-creature-Nahkriin.jpg"},{"name":"Ahzidal","rarity":"epic","id":"ahzidal","subtitle":"Creature","details":"A dragon priest of fire buried beneath Kolbjorn Barrow on Solstheim, the first Nord enchanter, consumed by revenge.","image":"https://images.uesp.net/f/f8/SR-creature-Ahzidal.jpg"},{"name":"Zahkriisos","rarity":"epic","id":"zahkriisos","subtitle":"Creature","details":"A dragon priest of lightning sealed in Bloodskal Barrow on Solstheim, behind a door opened only by the Bloodskal Blade.","image":"https://images.uesp.net/e/e7/SR-creature-Zahkriisos.jpg"},{"name":"Legendary Dragon","rarity":"epic","id":"legendary-dragon","subtitle":"Creature","details":"The strongest of all dragon breeds, appearing only before a seasoned Dragonborn, armoured in dark, jagged scales.","image":"https://images.uesp.net/c/cd/SR-creature-Legendary_Dragon.jpg"},{"name":"Revered Dragon","rarity":"epic","id":"revered-dragon","subtitle":"Creature","details":"An orange-scaled dragon breed of immense power that breathes a life-draining mist and dives on prey from the clouds.","image":"https://images.uesp.net/1/1d/SR-creature-Revered_Dragon.jpg"},{"name":"Ancient Dragon","rarity":"epic","id":"ancient-dragon","subtitle":"Creature","details":"An aged, battle-scarred dragon far stronger than its younger kin, hunting the skies late in a Dragonborn's journey.","image":"https://images.uesp.net/0/0a/SR-creature-Ancient_Dragon.jpg"},{"name":"Shadowmere","rarity":"epic","id":"shadowmere","subtitle":"Creature","details":"The Dark Brotherhood's undying black horse, a near-invincible mount with glowing red eyes who always returns from death.","image":"https://images.uesp.net/b/be/SR-creature-Shadowmere.jpg"},{"name":"Dukaan","rarity":"rare","id":"dukaan","subtitle":"Creature","details":"A dragon priest of frost entombed in White Ridge Barrow on Solstheim, master of ice storms and freezing shouts.","image":"https://images.uesp.net/d/d5/SR-creature-Dukaan.jpg"},{"name":"Krosis","rarity":"rare","id":"krosis","subtitle":"Creature","details":"A dragon priest who bursts from his sarcophagus at Shearpoint, a dragon burial wall in the Pale watched over by a dragon.","image":"https://images.uesp.net/3/36/SR-creature-Krosis.jpg"},{"name":"Otar","rarity":"rare","id":"otar","subtitle":"Creature","details":"A mad dragon priest sealed away in Ragnvald by two skull keys, guarded in death by the warlords Saerek and Torsten.","image":"https://images.uesp.net/5/50/SR-creature-Otar_the_Mad.jpg"},{"name":"Rahgot","rarity":"rare","id":"rahgot","subtitle":"Creature","details":"A dragon priest whose cult at Forelhost chose mass poison over surrender when the dragons' war turned against them.","image":"https://images.uesp.net/2/21/SR-creature-Rahgot.jpg"},{"name":"Vokun","rarity":"rare","id":"vokun","subtitle":"Creature","details":"A dragon priest buried in the High Gate Ruins in the Pale, rising to defend his tomb with fire and undead servants.","image":"https://images.uesp.net/8/84/SR-creature-Vokun.jpg"},{"name":"Volsung","rarity":"rare","id":"volsung","subtitle":"Creature","details":"A dragon priest entombed high in Volskygge's peaks in Haafingar, rising from a sarcophagus above the mountain clouds.","image":"https://images.uesp.net/b/b2/SR-creature-Volsung.jpg"},{"name":"Hevnoraak","rarity":"rare","id":"hevnoraak","subtitle":"Creature","details":"A dragon priest in Valthume who planned his own resurrection, draining his blood into urns tended by draugr cultists.","image":"https://images.uesp.net/0/0b/SR-creature-Hevnoraak.jpg"},{"name":"Mirmulnir","rarity":"rare","id":"mirmulnir","subtitle":"Creature","details":"The first dragon the Dragonborn fights, attacking Whiterun's Western Watchtower as dragons return to Skyrim's skies.","image":"https://images.uesp.net/3/30/SR-creature-Mirmulnir.jpg"},{"name":"Elder Dragon","rarity":"rare","id":"elder-dragon","subtitle":"Creature","details":"A bronze-scaled dragon breed stronger than blood and frost dragons, breathing fire and killing frost with equal fury.","image":"https://images.uesp.net/8/88/SR-creature-Elder_Dragon.jpg"},{"name":"Draugr Deathlord","rarity":"rare","id":"draugr-deathlord","subtitle":"Creature","details":"The mightiest of the draugr, an ancient Nord overlord who wields the full Unrelenting Force and ebony weapons.","image":"https://images.uesp.net/a/a8/SR-quest-Evil_in_Waiting_03.jpg"},{"name":"Dwarven Centurion","rarity":"rare","id":"dwarven-centurion","subtitle":"Creature","details":"A towering Dwemer automaton of brass and steam, immune to poison, frost and illusion, guarding the deepest ruins.","image":"https://images.uesp.net/0/09/SR-creature-Dwarven_Centurion.jpg"},{"name":"Blood Dragon","rarity":"uncommon","id":"blood-dragon","subtitle":"Creature","details":"A green-scaled dragon breed with a frilled head and savage bite, the first stronger kin most Dragonborn ever meet.","image":"https://images.uesp.net/d/d5/SR-creature-Blood_Dragon.jpg"},{"name":"Frost Dragon","rarity":"uncommon","id":"frost-dragon","subtitle":"Creature","details":"A white-scaled dragon that breathes killing frost, at home over Skyrim's snows, frozen northern seas and high peaks.","image":"https://images.uesp.net/a/af/SR-creature-Frost_Dragon.jpg"},{"name":"Vulthuryol","rarity":"uncommon","id":"vulthuryol","subtitle":"Creature","details":"A dragon sleeping hidden in Blackreach, summoned by striking the great glowing orb above the silent city's ruins.","image":"https://images.uesp.net/1/11/SR-creature-Vulthuryol.jpg"},{"name":"Vampire Lord","rarity":"uncommon","id":"vampire-lord","subtitle":"Creature","details":"The winged, hovering vampiric form granted by Lord Harkon's blood, wielding blood magic and draining life in battle.","image":"https://images.uesp.net/8/81/SR-skill-Vampire_Lord_%28Male%29.jpg"},{"name":"Falmer","rarity":"uncommon","id":"falmer","subtitle":"Creature","details":"The blind, twisted descendants of the Snow Elves, dwelling in darkness beneath Skyrim and warring on all surface folk.","image":"https://images.uesp.net/1/17/SR-creature-Falmer_02.jpg"},{"name":"Chaurus","rarity":"uncommon","id":"chaurus","subtitle":"Creature","details":"A venom-spitting insectoid beast kept as livestock by the Falmer, whose chitin makes armour and whose eggs fill caverns.","image":"https://images.uesp.net/4/43/SR-creature-Chaurus.jpg"},{"name":"Hagraven","rarity":"uncommon","id":"hagraven","subtitle":"Creature","details":"A monstrous half-woman, half-bird witch who traded her humanity for dark magic, ruling covens in the Reach's crags.","image":"https://images.uesp.net/2/25/SR-creature-Hagraven.jpg"},{"name":"Giant","rarity":"uncommon","id":"giant","subtitle":"Creature","details":"A towering herdsman of the tundra whose club swings can launch a victim skyward, and who wants only to tend his mammoths.","image":"https://images.uesp.net/0/0d/SR-creature-Giant_02.jpg"},{"name":"Mammoth","rarity":"uncommon","id":"mammoth","subtitle":"Creature","details":"A great woolly beast herded by giants, prized for its tusks, snout and the strong cheese made from its thick milk.","image":"https://images.uesp.net/6/64/SR-creature-Mammoth.jpg"},{"name":"Werewolf","rarity":"uncommon","id":"werewolf","subtitle":"Creature","details":"The beast form of the Companions' inner Circle, blessed — or cursed — by Hircine with hunger, claws and moonlit rage.","image":"https://images.uesp.net/9/97/SR-creature-Werewolf_02.jpg"},{"name":"Gargoyle","rarity":"uncommon","id":"gargoyle","subtitle":"Creature","details":"A stone statue in vampire strongholds that bursts suddenly to life, striking with claws while its masters watch.","image":"https://images.uesp.net/8/8e/SR-creature-Gargoyle.jpg"},{"name":"Seeker","rarity":"uncommon","id":"seeker","subtitle":"Creature","details":"A floating, tentacled servant of Hermaeus Mora drifting through Apocrypha, blasting intruders with eldritch bolts.","image":"https://images.uesp.net/0/05/SR-creature-Seeker.jpg"},{"name":"Lurker","rarity":"uncommon","id":"lurker","subtitle":"Creature","details":"A huge amphibious guardian that rises from Apocrypha's dark waters to crush intruders with stomps and tentacles.","image":"https://images.uesp.net/4/42/SR-creature-Lurker.jpg"},{"name":"Wispmother","rarity":"uncommon","id":"wispmother","subtitle":"Creature","details":"A spectral sorceress haunting Skyrim's cold wild places, splitting into wisps that harry travellers in the dark.","image":"https://images.uesp.net/c/c1/SR-creature-Wispmother.jpg"},{"name":"Storm Atronach","rarity":"uncommon","id":"storm-atronach","subtitle":"Creature","details":"A Daedric elemental of crackling lightning bound into levitating stone, hurling storm bolts at anything that strays near.","image":"https://images.uesp.net/7/7c/SR-creature-Storm_Atronach.jpg"},{"name":"Spriggan","rarity":"common","id":"spriggan","subtitle":"Creature","details":"A tree-like nature spirit guarding sacred groves, commanding forest animals to swarm attackers in defence of the wild.","image":"https://images.uesp.net/9/9c/SR-creature-Spriggan.jpg"},{"name":"Troll","rarity":"common","id":"troll","subtitle":"Creature","details":"A three-eyed, ape-armed brute of cave and hillside whose wounds knit shut in moments unless they are sealed with fire.","image":"https://images.uesp.net/b/bf/SR-creature-Troll.jpg"},{"name":"Frost Troll","rarity":"common","id":"frost-troll","subtitle":"Creature","details":"A white-furred troll haunting the snows, stronger and tougher than its lowland kin, a terror on the road to High Hrothgar.","image":"https://images.uesp.net/f/f4/SR-creature-Frost_Troll.jpg"},{"name":"Frost Atronach","rarity":"common","id":"frost-atronach","subtitle":"Creature","details":"A hulking Daedric elemental of jagged ice that smashes foes with frozen fists and shrugs off most mortal blades.","image":"https://images.uesp.net/1/1f/SR-creature-Frost_Atronach.jpg"},{"name":"Flame Atronach","rarity":"common","id":"flame-atronach","subtitle":"Creature","details":"A fiery Daedric summon wreathed in flame that scorches any nearby foes and explodes violently when it is killed.","image":"https://images.uesp.net/5/5a/SR-creature-Flame_Atronach.jpg"},{"name":"Ash Spawn","rarity":"common","id":"ash-spawn","subtitle":"Creature","details":"A reanimated guardian of ash and cinder rising from Solstheim's wastes to besiege Raven Rock and its ruined forts.","image":"https://images.uesp.net/4/41/SR-creature-Ash_Spawn_4.jpg"},{"name":"Netch","rarity":"common","id":"netch","subtitle":"Creature","details":"A floating, jellyfish-like herd animal native to Morrowind and Solstheim, docile unless its calves are threatened.","image":"https://images.uesp.net/b/b0/SR-creature-Bull_Netch.jpg"},{"name":"Ice Wraith","rarity":"common","id":"ice-wraith","subtitle":"Creature","details":"A translucent flying serpent of living ice haunting Skyrim's frozen wastes, striking from the snow without warning.","image":"https://images.uesp.net/d/da/SR-creature-Ice_Wraith.jpg"},{"name":"Dwarven Sphere","rarity":"common","id":"dwarven-sphere","subtitle":"Creature","details":"A Dwemer automaton that patrols ruins as a rolling metal ball, unfolding blades and arms when it finds intruders.","image":"https://images.uesp.net/4/47/SR-creature-Dwarven_Sphere.jpg"},{"name":"Frostbite Spider","rarity":"common","id":"frostbite-spider","subtitle":"Creature","details":"A venomous spider infesting caves and ruins across Skyrim, spitting poison and dropping from ceilings in ambush.","image":"https://images.uesp.net/1/16/SR-creature-Frostbite_Spider.jpg"},{"name":"Sabre Cat","rarity":"common","id":"sabre-cat","subtitle":"Creature","details":"A huge fanged predator stalking Skyrim's plains and snows, fast enough to run down deer — and unwary travellers.","image":"https://images.uesp.net/0/0f/SR-creature-Sabre_Cat.jpg"},{"name":"Cave Bear","rarity":"common","id":"cave-bear","subtitle":"Creature","details":"A massive, aggressive bear dwelling in caves and mountain forests, quick to charge anything that enters its territory.","image":"https://images.uesp.net/5/56/SR-creature-Bear.jpg"},{"name":"Wolf","rarity":"common","id":"wolf","subtitle":"Creature","details":"A pack hunter roaming the wilderness roads of every hold, harrying travellers, deer and lone adventurers alike.","image":"https://images.uesp.net/3/3c/SR-creature-Wolf.jpg"},{"name":"Skeever","rarity":"common","id":"skeever","subtitle":"Creature","details":"A giant, disease-ridden rat infesting sewers, cellars and ruins, swarming in packs beneath Skyrim's great cities.","image":"https://images.uesp.net/b/bc/SR-creature-Skeever.jpg"},{"name":"Mudcrab","rarity":"common","id":"mudcrab","subtitle":"Creature","details":"A small armoured crab snapping at ankles along every shoreline, more nuisance than threat — until a giant one appears.","image":"https://images.uesp.net/9/93/SR-creature-Mudcrab.jpg"}]});
